{
  "notes": [
    {
      "title": "Helena World Chronicle files antitrust suit against Google and Alphabet",
      "summary": "Arkansas publisher Helena World Chronicle filed a class action lawsuit in U.S. District Court in D.C. accusing Google and Alphabet of anticompetitive behavior under the Sherman Act, alleging they siphon off content, readers, and ad revenue through AI technologies like Search Generative Experience (SGE) and Bard, and older tools like the Knowledge Graph launched in May 2012."
    },
    {
      "title": "Knowledge Graph data extraction and scale",
      "summary": "The Knowledge Graph, launched in May 2012, grew to 500 billion facts about 5 billion entities by 2020; the lawsuit alleges Google compiled this database by extracting information from publishers' websites and open source/licensed databases, misappropriating content that 'starves the free press' and costs publishers billions of dollars."
    },
    {
      "title": "AI impact on publisher traffic and revenue",
      "summary": "A Wall Street Journal report cited by the suit states that if Google integrated AI into search, 75% of the time AI would answer queries without a click-through to publisher sites, potentially causing publishers to lose 20-40% of traffic; currently, Google drives nearly 40% of publisher traffic."
    },
    {
      "title": "Publisher response and lawsuit claims regarding SGE",
      "summary": "While Axel Springer licensed news to OpenAI for AI training, the lawsuit claims Google's AI-based search, specifically SGE, was implemented to discourage users from visiting publisher websites by keeping them in Google's 'walled garden' and plagiarizing content, noting publishers cannot block SGE as it uses the same GoogleBot crawler."
    }
  ]
}

